std::string convertMarkdownToHTML(const std::string& markdown) {
    std::sstream ss;
    ss << markdown;

    std::string line;
    while (std::getline(ss, line)) {
        std::string html;

        if (line.empty()) {
            // Line break - append HTML for `br` element
            html += "<br>";
        } else {
            auto it = line.begin();

            // While there still is content in the current line...
            while (it!= line.end()) {

                const char* delimiter_begin = nullptr; // start of delimiter range
                const char* delimiter_end = nullptr;   // end of delimiter range

                std::size_t delimiter_len = 0;
                bool is_delimiter_open = false;

                std::size_t pos = it - line.begin(); // character index within line

                // Find the next delimiter or line break
                while ((delimiter_begin == nullptr || it!= delimiter_begin) &&
                       pos < static_cast<std::size_t>(line.size())) {

                    if (*it == '-') { // horizontal rule
                        html += "<hr>";

                        break;
                    }

                    switch (*it) {
                        case '#':
                            delimiter_begin = it;
                            delimiter_len = 1;
                            break;

                        case '*':
                            delimiter_begin = it;
                            delimiter_len = 1;
                            break;

                        case '_':
                            delimiter_begin = it;
                            delimiter_len = 1;
                            break;

                        case '[':
                            delimiter_begin = it;
                            delimiter_end = std::strchr(it + 1, ']');
                            delimiter_len = delimiter_end? static_cast<unsigned int>((delimiter_end - (it+1))) : 0;
                            break;

                        case '`':
                            delimiter_begin = it;
                            delimiter_end = std::find(delimiter_begin, line.end(), '`');
                            delimiter_len = delimiter_end == line.end()? 0 : static_cast<unsigned int>((delimiter_end - (it+1)));
                            is_delimiter_open = *it == '`';
                            break;

                        default:
                            ++it;
                            continue;
                    }
                    ++it;

                    if(delimiter_end!= nullptr && delimiter_end!= delimiter_begin){ // close existing delimiter tag if open
                        while(!is_delimiter_open){
                            --delimiter_end;
                            is_delimiter_open = (*(--delimiter_end)) == '`'; // check if last character was opening tickmark
                        }
                        is_delimiter_open = false;
                        html += std::string("\n" + std::string(delimiter_begin, delimiter_end+1), '<', '>');
                    } 
                }

                if (delimiter_end!= nullptr && delimiter_end!= delimiter_begin) { // add HTML for found delimiter
                    auto iter_range = MARKDOWN_TO_HTML_TAG.find(std::string(delimiter_begin, delimiter_end+1));

                    if (iter_range!= MARKDONW_TO_HTML_TAG.end()) {
                        const std::string &tag = iter_range->second.first;

                        if(iter_range->second.second){
                            html += std::string("<" + tag);
                        } else{
                            html += std::string("<" + tag + ">");
                        }

                        delimiter_begin += delimiter_len;
                        it = delimiter_end + delimiter_len; // move iterator past delimiter

                        while (it!= line.end()) {
                            if (*(it++) == '|') { // table separator
                                if (!html.empty())
                                    html += std::string("</td></tr>\n");

                                html += "<tr><td>";
                            }
                        }

                        if(iter_range->second.second){
                            // If `is_delimiter_open` is true, means the delimiter has backticks around it (```text```)
                            // Then we need to add them as attributes.
                            if(is_delimiter_open){
                                html += std::string(" class='highlighter'>") + std::string(delimiter_begin, line.end());
                                html += "</";
                            }else{
                                html += std::string(delimiter_end, delimiter_begin);

                                it = delimiter_end + delimiter_len;
                            }
                            html += iter_range->second.first + "></" + iter_range->second.first + ">";
                        } else {
                            // Without the open/close attribute, just append any remaining characters before next delimiter/end-of-line
                            html += std::string(delimiter_begin, it);

                            it = line.end();
                        }
                    }
                } else {
                    // Append any remaining characters before next delimiter/end-of-line
                    html += std::string(it, line.end());

                    it = line.end();
                }
            }

            if(!html.empty()) {
                html += "\n"; // Add newline after every non-empty line
            }
        }

        if (line.empty()) {
            line += "\n"; // Add extra newline at the beginning/end of file to avoid losing empty lines on conversion
        }

        line = html;
    }

    return line;
}

int main() {
